#!/usr/bin/env bash
# Regenerate every checked-in oracle save from its setup script.
#
# The saves in this directory are test data: booting both engines from the
# same file is how the save-mode oracle compares interactions that need state
# a fresh new game does not have. They are checked in so they stay loadable
# forever; this script proves they can still be regenerated byte-for-byte
# from the current pack (the .lua next to each .dat is the authored state).
#
# Usage:
#   scripts/oracle-saves.sh [SAVEDAT...]
#
# Environment:
#   ARKLAY_BIN       arklay binary (default target/release/arklay)
#   ARKLAY_RE1_PACK  game pack (default games/re1.akpak)
#   ARKLAY_LANGUAGE  display language tag (default ja-JP for the JPN assets)
#
# Each save's boot (room, player, character) is recorded in the file's entry
# in README.md and at the top of its .lua: the CLI always boots
# `--ui game --room <room> --player <p> --character <c>` with the script
# applied before the state is serialized.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ARK_BIN="${ARKLAY_BIN:-$REPO_ROOT/target/release/arklay}"
PACK="${ARKLAY_RE1_PACK:-$REPO_ROOT/games/re1.akpak}"
LANGUAGE="${ARKLAY_LANGUAGE:-ja-JP}"

SAVE_DIR="$REPO_ROOT/oracle/saves"
cd "$SAVE_DIR"

# name|room|player|character
SAVES=(
    "pause_chris_101|101|0|0"
    "file_chris_101|101|0|0"
    "map_chris_101|101|0|0"
    "radio_chris_101|101|0|0"
    "combine_chris_101|101|0|0"
    "use_chris_101|101|0|0"
    "equip_chris_101|101|0|0"
    "itembox_chris_118|118|0|0"
    "typewriter_chris_118|118|0|0"
)

selected=("$@")
if [ ${#selected[@]} -eq 0 ]; then
    for row in "${SAVES[@]}"; do
        selected+=("${row%%|*}")
    done
fi

for name in "${selected[@]}"; do
    row=""
    for candidate in "${SAVES[@]}"; do
        if [[ "${candidate%%|*}" == "$name" ]]; then
            row="$candidate"
        fi
    done
    if [[ -z "$row" ]]; then
        echo "unknown save '$name'" >&2
        exit 2
    fi
    IFS='|' read -r _ room player character <<<"$row"
    echo "== $name (room $room player $player character $character)"
    "$ARK_BIN" "$PACK" \
        --ui game --room "$room" --player "$player" --character "$character" \
        --setup-script "$SAVE_DIR/$name.lua" \
        --save-out "$SAVE_DIR/$name.dat" \
        --language "$LANGUAGE" --no-mods
done
echo "regenerated ${#selected[@]} save(s) in $SAVE_DIR"
